const j=$input.first().json||{};
const all=j.data||[];
const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
sd.altaSync={ totalInWorkspace: all.length, truncated: !!j.hasMore, campaigns: [] };
const active=all.filter(c=>c.status==='active'&&!c.isArchived);
return active.map(c=>({ json: { campaignId:c.id, campaignName:c.name, status:String(c.status||'').toUpperCase(), launchedAt:c.launchedAt||c.createdAt||'' } }));

let s={totalInWorkspace:0,truncated:false,campaigns:[]};
let t={checked:0,updated:0,skipped:[]};
let rs=0; let launch={};
try{ const sd=$getWorkflowStaticData('global'); s=sd.altaSync||s; t=sd.altaThreads||t; rs=sd.runStartedAt||0; launch=sd.launch||{}; }catch(e){}
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const lines=s.campaigns.map(c=>'- **'+c.name+':** '+nf(c.leads)+' leads');
const warn=s.truncated?['**WARNING:** workspace has >100 campaigns, list truncated']:[];
const authFailed=t.skipped.some(p=>String(p).includes('AUTH FAILED'));
const zeroUpsert=s.totalInWorkspace>0 && s.campaigns.length===0;
const errCount=t.skipped.length + (authFailed && !t.skipped.length ? 1 : 0) + (zeroUpsert ? 1 : 0);
const zeroWarn=zeroUpsert?['**ERROR:** 0 campaigns upserted while workspace has '+s.totalInWorkspace+' campaign(s)']:[];
const parts=['**'+s.campaigns.length+' active of '+s.totalInWorkspace+' campaigns in workspace**'];
// This machine serves the one Alta workspace (Dave.io); a client filter on the launch row is noted, not applied.
if(launch.clientFilter && launch.clientFilter!=='reclCOYRBgMowJd8G') parts.push('**Scope:** launch row Client ignored, this sync serves the Dave.io Alta workspace only');
if(warn.length) parts.push(warn.join('\n'));
if(zeroWarn.length) parts.push(zeroWarn.join('\n'));
if(lines.length) parts.push('**Campaigns**\n'+lines.join('\n'));
parts.push('**Threads:** '+nf(t.checked)+' prospects checked · '+nf(t.updated)+' threads refreshed');
if(t.skipped.length) parts.push('**Thread problems ('+t.skipped.length+')**\n'+t.skipped.map(p=>'- '+p).join('\n'));
const desc=parts.join('\n\n');
return [{ json: {
 'Automation':'Sync Alta Campaigns to Hub',
 'Client': ['reclCOYRBgMowJd8G'],
 'Status': errCount>0 ? 'Succeeded with errors' : 'Succeeded',
 'Run at': $now.toISO(),
 'Records In': s.campaigns.length,
 'Records Out': s.campaigns.length,
 'Errors': errCount,
 'Target': 'Campaigns + Prospects',
 'Trigger': launch.trigger||'schedule',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': desc
}}];

const c=$('Loop Campaigns').first().json;
let leads=0;
for(const it of $input.all()){ const j=it.json||{}; leads+=(Array.isArray(j.data)?j.data.length:0); }
const sd=$getWorkflowStaticData('global');
sd.altaSync.campaigns.push({name:c.campaignName, leads});
return [{ json: {
  'Campaign': c.campaignName,
  'Campaign ID': c.campaignId,
  'Client': ['reclCOYRBgMowJd8G'],
  'Sequencer': 'Alta',
  'Channel': 'Multi',
  'Status': c.status,
  'Leads': leads,
  'Created': c.launchedAt,
  'Last Synced': $now.toISO()
}}];

const t=$input.first().json||{};
const prev=$('Alta Get Token').first().json||{};
const sd=$getWorkflowStaticData('global');
sd.altaThreads={checked:0,updated:0,skipped:[]};
const access=t.access_token||'';
if(!access) return [{ json: { _authFailed:true, detail: JSON.stringify(t).slice(0,300) } }];
return [{ json: { access_token:access, refresh_token:t.refresh_token||prev.refresh_token||'', expires_at:new Date(Date.now()+((t.expires_in||86400)*1000)).toISOString() } }];

const sd=$getWorkflowStaticData('global');
sd.altaThreads.skipped.push('AUTH FAILED - re-auth needed via Alta OAuth Callback flow: '+(($input.first().json||{}).detail||''));
return [{ json: { ok:false } }];

const items=$input.all().filter(it=>it&&it.json&&it.json.id);
if(!items.length) return [{ json: { _empty:true } }];
return items;

const parse=(raw)=>{ try{ let s=raw; if(typeof s==='object'&&s.data)s=s.data; if(typeof s!=='string')s=JSON.stringify(s); const m=s.match(/data:\s*(\{[\s\S]*\})/); const rpc=JSON.parse(m?m[1]:s); const txt=rpc.result&&rpc.result.content&&rpc.result.content[0]&&rpc.result.content[0].text; return txt?JSON.parse(txt):null; }catch(e){ return null; } };
const pr=$('Alta Thread Loop').first().json; const prf=pr.fields||pr;
const crow=$('Get Campaign Row').first().json||{}; const cf=crow.fields||crow;
const campaignId=cf['Campaign ID']||'';
const prospectId=prf['Alta Prospect ID']||'';
const li=parse($('MCP Get Rep LI').first().json);
const em=parse($('MCP Get Rep Email').first().json);
const repId=(li&&li.repId)||(em&&em.repId)||'';
const sd=$getWorkflowStaticData('global');
sd.altaThreads.checked++;
if(!campaignId||!prospectId||!repId){ sd.altaThreads.skipped.push((prf.Name||pr.id)+' (missing'+(!campaignId?' campaignId':'')+(!prospectId?' prospectId':'')+(!repId?' repId':'')+')'); return [{ json: { _skip:true } }]; }
const mk=(tool,type)=>({jsonrpc:'2.0',id:2,method:'tools/call',params:{name:tool,arguments:{campaignId,prospectId,repId,type,tag:null,unread:false}}});
const out=[];
for(const type of ['campaign','received','manual','reply_agent']){ out.push({ json: { callBody: mk('list_linkedin_messages',type) } }); out.push({ json: { callBody: mk('list_email_messages',type) } }); }
return out;

const parse=(raw)=>{ try{ let s=raw; if(typeof s==='object'&&s.data)s=s.data; if(typeof s!=='string')s=JSON.stringify(s); const m=s.match(/data:\s*(\{[\s\S]*\})/); const rpc=JSON.parse(m?m[1]:s); const txt=rpc.result&&rpc.result.content&&rpc.result.content[0]&&rpc.result.content[0].text; return txt?(txt.startsWith('{')?JSON.parse(txt):txt):null; }catch(e){ return null; } };
const msgs=[];
for(const it of $input.all()){
  const r=parse(it.json);
  if(!r||typeof r!=='object') continue;
  const arr=r.linkedinMessages||r.emailMessages||[];
  for(const m of arr){ if(m&&m.id) msgs.push(m); }
}
const pr=$('Alta Thread Loop').first().json; const prf=pr.fields||pr;
const seen=new Set(); const uniq=[];
for(const m of msgs){ if(!seen.has(m.id)){ seen.add(m.id); uniq.push(m); } }
uniq.sort((a,b)=>new Date(a.happenedAt||a.createdAt||0)-new Date(b.happenedAt||b.createdAt||0));
const fmtTs=(ts)=>{const d=new Date(ts);if(isNaN(d.getTime()))return '';return d.toLocaleString('sv-SE',{timeZone:'Asia/Jerusalem'}).slice(0,16);};
const blocks=[]; const themTs=[]; const usTs=[];
for(const m of uniq){
  const txt=String(m.text||m.body||'').replace(/\s+/g,' ').trim().slice(0,400);
  if(txt.length<2) continue;
  const dir=(m.type==='received')?'THEM':'US';
  const t=m.happenedAt||m.createdAt||'';
  if(dir==='THEM'&&t)themTs.push(t); if(dir==='US'&&t)usTs.push(t);
  blocks.push('**['+fmtTs(t)+'] '+dir+':**\n'+txt);
}
let thread=blocks.join('\n\n');
if(thread.length>9000)thread=thread.slice(-9000);
const iso=(t)=>{const d=new Date(t);return isNaN(d.getTime())?'':d.toISOString();};
const firstThem=themTs.length?iso(themTs[0]):(prf['First Engagement']||'');
const lastThem=themTs.length?iso(themTs[themTs.length-1]):(prf['Last Engaged']||'');
const lastUs=usTs.length?iso(usTs[usTs.length-1]):(prf['Last Touch']||'');
const current=String(prf['Conversation Thread']||'').trim();
if(!thread||(thread.trim()===current && (!lastThem||prf['Last Engaged']) && (!lastUs||prf['Last Touch']))) return [{ json: { _skip:true } }];
const sd=$getWorkflowStaticData('global');
sd.altaThreads.updated++;
return [{ json: { prospectId: pr.id, 'Conversation Thread': thread, 'First Engagement': firstThem, 'Last Engaged': lastThem, 'Last Touch': lastUs } }];

// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd=$getWorkflowStaticData('global');
let launch=null;
try{ const r=$('Fetch Launch Record').first().json; if(r&&r.id) launch=r; }catch(e){}
const f=(launch&&launch.fields)||launch||{};
const cl=Array.isArray(f.Client)&&f.Client.length?f.Client[0]:'';
const clientFilter=(cl&&typeof cl==='object')?String(cl.id||''):String(cl||'');
sd.launch={ recordId: launch?String(launch.id):'', trigger: launch?'form':'schedule', clientFilter, startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];
